'use strict';
const __modules = Object.create(null);
__modules['./utils'] = function(module, exports, __require) {
'use strict';
const TASK_SCHEMA_VERSION = 'chelsea_tasks_table_v1';

const COMMAND_CONTRACT_VERSION = 'chelsea_task_command_v1';

function fail(code, message, details) {
  const error = new Error(message || code);
  error.code = code;
  if (details !== undefined) error.details = details;
  throw error;
}

function assert(condition, code, message, details) {
  if (!condition) fail(code, message, details);
}

function isPlainObject(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value) &&
    (Object.getPrototypeOf(value) === Object.prototype || Object.getPrototypeOf(value) === null);
}

function stableValue(value) {
  if (Array.isArray(value)) return value.map(stableValue);
  if (!isPlainObject(value)) return value;
  const result = {};
  for (const key of Object.keys(value).sort()) result[key] = stableValue(value[key]);
  return result;
}

function canonicalJson(value) {
  return JSON.stringify(stableValue(value));
}

function deterministicId(prefix, parts) {
  assert(/^[a-z][a-z0-9_]*$/.test(prefix), 'invalid_id_prefix', 'Invalid deterministic ID prefix');
  return `${prefix}_${hash128(canonicalJson(parts))}`;
}

function parseIso(value, fieldName) {
  assert(typeof value === 'string' && /Z$/.test(value), 'invalid_utc_iso', `${fieldName || 'value'} must be UTC ISO ending in Z`);
  const date = new Date(value);
  assert(Number.isFinite(date.getTime()) && date.toISOString() === value, 'invalid_utc_iso', `Invalid ${fieldName || 'UTC instant'}`);
  return date;
}

function asString(value, fieldName, options) {
  const opts = options || {};
  assert(typeof value === 'string', 'invalid_string', `${fieldName} must be a string`);
  const result = opts.trim === false ? value : value.trim();
  const min = opts.min === undefined ? 0 : opts.min;
  const max = opts.max === undefined ? 4096 : opts.max;
  assert(result.length >= min && result.length <= max, 'invalid_string_length', `${fieldName} length is outside allowed bounds`);
  return result;
}

function asInteger(value, fieldName, min, max) {
  assert(Number.isInteger(value), 'invalid_integer', `${fieldName} must be an integer`);
  assert(value >= min && value <= max, 'integer_out_of_range', `${fieldName} is outside allowed bounds`);
  return value;
}

function oneOf(value, allowed, fieldName) {
  assert(allowed.includes(value), 'invalid_enum', `${fieldName} has an unsupported value`, { fieldName, value });
  return value;
}

function exactKeys(object, allowed, fieldName) {
  assert(isPlainObject(object), 'invalid_object', `${fieldName} must be an object`);
  const unexpected = Object.keys(object).filter((key) => !allowed.includes(key));
  assert(unexpected.length === 0, 'unknown_fields', `${fieldName} contains unknown fields`, unexpected);
}

function deepClone(value) {
  return value === undefined ? undefined : JSON.parse(JSON.stringify(value));
}

function appendHistory(historyJson, event) {
  let history = [];
  if (historyJson) {
    try {
      history = JSON.parse(historyJson);
    } catch (_) {
      fail('malformed_history_json', 'historyJson is malformed');
    }
  }
  assert(Array.isArray(history), 'malformed_history_json', 'historyJson must contain an array');
  history.push(event);
  return canonicalJson(history.slice(-20));
}

function mutationToken(recordId, previousVersion, mutationType, sourceId) {
  return deterministicId('mut', [recordId, previousVersion, mutationType, sourceId || 'system']);
}

function actionToken(recordId, type, at, sequence, rowVersion) {
  if (type === 'none') return '';
  return deterministicId('act', [recordId, type, at, sequence, rowVersion]);
}

module.exports = { TASK_SCHEMA_VERSION, COMMAND_CONTRACT_VERSION, fail, assert, isPlainObject, stableValue, canonicalJson, deterministicId, parseIso, asString, asInteger, oneOf, exactKeys, deepClone, appendHistory, mutationToken, actionToken };
};
__modules['./semantic'] = function(module, exports, __require) {
'use strict';
const { COMMAND_CONTRACT_VERSION, asInteger, asString, assert, canonicalJson, exactKeys, isPlainObject, oneOf } = __require('./utils');
const OPERATIONS = [
  'create_task', 'create_reminder', 'add_reminder', 'update_task', 'reschedule_task',
  'complete_task', 'snooze_task', 'skip_occurrence', 'cancel_task', 'list_tasks',
  'add_subtask', 'pause_series', 'resume_series', 'update_series', 'cancel_series',
  'answer_task_question', 'not_a_task_command',
];

const TOP_KEYS = [
  'contractVersion', 'operation', 'targetRef', 'title', 'description', 'taskKind',
  'priority', 'tags', 'schedule', 'recurrence', 'reminderPolicy', 'completionRequired',
  'seriesMutationScope', 'listKind', 'answerAction', 'clarificationNeeded', 'clarificationReason',
  'fieldPresence',
];

const PATCH_FIELDS = Object.freeze(['title', 'description', 'taskKind', 'priority', 'tags', 'schedule', 'recurrence', 'reminderPolicy', 'completionRequired', 'seriesMutationScope']);

const FORBIDDEN_IDENTITY_KEYS = [
  'tenantId', 'tenantSafe', 'taskTableId', 'tableId', 'tableName', 'ownerUserId',
  'recordId', 'taskId', 'seriesId', 'status', 'rowVersion', 'actionToken', 'idempotencyKey',
];

function parseSemanticJson(value) {
  let parsed = value;
  if (typeof value === 'string') {
    const text = value.trim();
    assert(text.startsWith('{') && text.endsWith('}'), 'malformed_model_contract', 'Model result must be one JSON object without prose/code fences');
    try { parsed = JSON.parse(text); } catch (_) {
      assert(false, 'malformed_model_contract', 'Model result is not valid JSON');
    }
  }
  assert(isPlainObject(parsed), 'malformed_model_contract', 'Model result must be an object');
  // Identity-like model fields are ignored by design; all other unknown fields fail closed.
  const clean = {};
  for (const [key, item] of Object.entries(parsed)) {
    if (!FORBIDDEN_IDENTITY_KEYS.includes(key)) clean[key] = item;
  }
  exactKeys(clean, TOP_KEYS, 'semantic contract');
  assert(clean.contractVersion === COMMAND_CONTRACT_VERSION, 'malformed_model_contract', 'Unsupported semantic contract version');
  const operation = oneOf(clean.operation, OPERATIONS, 'operation');
  const creationOperation = ['create_task', 'create_reminder', 'add_subtask'].includes(operation);
  const derivedPresence = Object.keys(clean).filter((key) => PATCH_FIELDS.includes(key));
  const fieldPresence = clean.fieldPresence === undefined || clean.fieldPresence === null
    ? derivedPresence
    : requireArray(clean.fieldPresence, 'fieldPresence').map((key) => oneOf(key, PATCH_FIELDS, 'fieldPresence[]'));
  assert(new Set(fieldPresence).size === fieldPresence.length, 'malformed_model_contract', 'fieldPresence cannot contain duplicates');
  const result = {
    contractVersion: COMMAND_CONTRACT_VERSION,
    operation,
    targetRef: nullableString(clean.targetRef, 'targetRef', 160),
    title: optionalString(clean.title, 'title', 240),
    description: optionalString(clean.description, 'description', 4000),
    taskKind: clean.taskKind === null || clean.taskKind === undefined || clean.taskKind === ''
      ? null : oneOf(clean.taskKind, ['action', 'reminder', 'wish', 'habit', 'goal'], 'taskKind'),
    priority: clean.priority === undefined || clean.priority === null ? (creationOperation ? 2 : null) : asInteger(clean.priority, 'priority', 0, 4),
    tags: clean.tags === undefined || clean.tags === null ? (creationOperation ? [] : null) : validateTags(clean.tags),
    schedule: validateSchedule(clean.schedule),
    recurrence: validateRecurrence(clean.recurrence),
    reminderPolicy: validateReminderPolicy(clean.reminderPolicy),
    completionRequired: clean.completionRequired === undefined || clean.completionRequired === null
      ? null : requireBoolean(clean.completionRequired, 'completionRequired'),
    seriesMutationScope: clean.seriesMutationScope === undefined || clean.seriesMutationScope === null
      ? null : oneOf(clean.seriesMutationScope, ['current_occurrence', 'current_and_future', 'future_only', 'entire_series'], 'seriesMutationScope'),
    listKind: clean.listKind === undefined || clean.listKind === null
      ? null : oneOf(clean.listKind, ['today', 'tomorrow', 'week', 'overdue', 'backlog', 'reminders', 'recurring', 'goals'], 'listKind'),
    answerAction: clean.answerAction === undefined || clean.answerAction === null
      ? null : oneOf(clean.answerAction, ['done', 'not_done', 'snooze', 'reschedule', 'cancel', 'skip_occurrence', 'update_series', 'cancel_series'], 'answerAction'),
    clarificationNeeded: clean.clarificationNeeded === true,
    clarificationReason: nullableString(clean.clarificationReason, 'clarificationReason', 500),
    fieldPresence: Array.from(new Set(fieldPresence)).sort(),
  };
  validateOperationShape(result);
  result.canonicalJson = canonicalJson(result);
  return result;
}

function validateSchedule(value) {
  if (value === undefined || value === null) return null;
  exactKeys(value, ['kind', 'timeRole', 'localDate', 'localTime', 'timezone', 'windowStartLocal', 'windowEndLocal', 'preferredTimeOfDay'], 'schedule');
  const kind = oneOf(value.kind, ['exact', 'date', 'window', 'none'], 'schedule.kind');
  const result = {
    kind,
    timeRole: oneOf(value.timeRole || (kind === 'window' ? 'window' : kind === 'none' ? 'none' : 'deadline'), ['start', 'deadline', 'reminder', 'window', 'none'], 'schedule.timeRole'),
    localDate: nullableDate(value.localDate, 'schedule.localDate'),
    localTime: nullableTime(value.localTime, 'schedule.localTime'),
    timezone: nullableString(value.timezone, 'schedule.timezone', 64),
    windowStartLocal: nullableLocalDateTime(value.windowStartLocal, 'schedule.windowStartLocal'),
    windowEndLocal: nullableLocalDateTime(value.windowEndLocal, 'schedule.windowEndLocal'),
    preferredTimeOfDay: value.preferredTimeOfDay === undefined || value.preferredTimeOfDay === null
      ? 'any' : oneOf(value.preferredTimeOfDay, ['morning', 'day', 'evening', 'any'], 'schedule.preferredTimeOfDay'),
  };
  if (kind === 'none') assert(!result.localDate && !result.localTime && !result.windowStartLocal && !result.windowEndLocal, 'malformed_model_contract', 'none schedule cannot contain time fields');
  if (kind === 'date') assert(result.localDate && !result.localTime, 'malformed_model_contract', 'date schedule requires localDate and forbids localTime');
  if (kind === 'exact') assert(result.localDate && result.localTime && result.timezone, 'malformed_model_contract', 'exact schedule requires localDate/localTime/timezone');
  if (kind === 'window') {
    assert(result.windowStartLocal && result.windowEndLocal && result.timezone, 'malformed_model_contract', 'window schedule requires both bounds/timezone');
    assert(result.windowEndLocal > result.windowStartLocal, 'malformed_model_contract', 'window local end must be after local start');
  }
  return result;
}

function validateRecurrence(value) {
  if (value === undefined || value === null) return null;
  exactKeys(value, ['version', 'frequency', 'interval', 'byWeekday', 'byMonthDay', 'localTime', 'allDay', 'maxOccurrences', 'timezone', 'dstGapPolicy', 'dstOverlapPolicy', 'startLocalDate', 'endLocalDate'], 'recurrence');
  assert(value.version === 'chelsea_recurrence_v1', 'malformed_model_contract', 'Unsupported recurrence version');
  const frequency = oneOf(value.frequency, ['daily', 'weekly'], 'recurrence.frequency');
  const interval = asInteger(value.interval === undefined ? 1 : value.interval, 'recurrence.interval', 1, 365);
  const allDay = requireBoolean(value.allDay === undefined ? false : value.allDay, 'recurrence.allDay');
  const byWeekday = value.byWeekday === undefined ? [] : requireArray(value.byWeekday, 'recurrence.byWeekday').map((day) => oneOf(day, ['MO', 'TU', 'WE', 'TH', 'FR', 'SA', 'SU'], 'recurrence.byWeekday[]'));
  assert(new Set(byWeekday).size === byWeekday.length, 'malformed_model_contract', 'Duplicate weekdays are forbidden');
  if (frequency === 'weekly') assert(byWeekday.length > 0, 'malformed_model_contract', 'Weekly recurrence requires byWeekday');
  if (frequency !== 'weekly') assert(byWeekday.length === 0, 'malformed_model_contract', 'byWeekday is weekly-only');
  assert(value.byMonthDay === undefined || (Array.isArray(value.byMonthDay) && value.byMonthDay.length === 0), 'malformed_model_contract', 'Monthly recurrence is outside bounded MVP core');
  const localTime = nullableTime(value.localTime, 'recurrence.localTime');
  assert(allDay ? !localTime : !!localTime, 'malformed_model_contract', 'allDay recurrence forbids localTime; timed recurrence requires it');
  const startLocalDate = nullableDate(value.startLocalDate, 'recurrence.startLocalDate');
  const endLocalDate = nullableDate(value.endLocalDate, 'recurrence.endLocalDate');
  assert(!startLocalDate || !endLocalDate || endLocalDate >= startLocalDate,
    'malformed_model_contract', 'recurrence.endLocalDate must not precede startLocalDate');
  return {
    version: 'chelsea_recurrence_v1', frequency, interval, byWeekday, byMonthDay: [], localTime,
    allDay,
    maxOccurrences: value.maxOccurrences === undefined || value.maxOccurrences === null ? null : asInteger(value.maxOccurrences, 'recurrence.maxOccurrences', 1, 100000),
    timezone: asString(value.timezone, 'recurrence.timezone', { min: 1, max: 64 }),
    dstGapPolicy: oneOf(value.dstGapPolicy || 'shift_forward', ['shift_forward'], 'recurrence.dstGapPolicy'),
    dstOverlapPolicy: oneOf(value.dstOverlapPolicy || 'earlier_offset', ['earlier_offset'], 'recurrence.dstOverlapPolicy'),
    startLocalDate, endLocalDate,
  };
}

function validateReminderPolicy(value) {
  if (value === undefined || value === null) return null;
  exactKeys(value, ['version', 'steps', 'completionCheck', 'defaultSnoozeMinutes', 'maxDeliveryAttempts', 'quietHoursMode'], 'reminderPolicy');
  assert(value.version === 'chelsea_reminder_policy_v1', 'malformed_model_contract', 'Unsupported reminder policy version');
  const steps = requireArray(value.steps, 'reminderPolicy.steps').map((step) => {
    exactKeys(step, ['kind', 'offsetMinutes'], 'reminder step');
    return { kind: oneOf(step.kind, ['before_due', 'at_due'], 'reminder step kind'), offsetMinutes: asInteger(step.offsetMinutes, 'offsetMinutes', 0, 525600) };
  });
  const unique = new Map();
  for (const step of steps) unique.set(`${step.kind}:${step.offsetMinutes}`, step);
  const completion = value.completionCheck || {};
  exactKeys(completion, ['enabled', 'delayMinutes', 'answerTtlMinutes', 'repeatAfterMinutes', 'maxQuestions'], 'completionCheck');
  assert(value.quietHoursMode === undefined || value.quietHoursMode === 'inherit',
    'quiet_hours_bypass_requires_trusted_confirmation', 'Model output cannot authorize quiet-hours bypass');
  return {
    version: 'chelsea_reminder_policy_v1',
    steps: Array.from(unique.values()).sort((a, b) => b.offsetMinutes - a.offsetMinutes),
    completionCheck: {
      enabled: requireBoolean(completion.enabled === undefined ? false : completion.enabled, 'completionCheck.enabled'),
      delayMinutes: asInteger(completion.delayMinutes === undefined ? 60 : completion.delayMinutes, 'completionCheck.delayMinutes', 0, 525600),
      answerTtlMinutes: asInteger(completion.answerTtlMinutes === undefined ? 4320 : completion.answerTtlMinutes, 'completionCheck.answerTtlMinutes', 1, 525600),
      repeatAfterMinutes: asInteger(completion.repeatAfterMinutes === undefined ? 1440 : completion.repeatAfterMinutes, 'completionCheck.repeatAfterMinutes', 1, 525600),
      maxQuestions: asInteger(completion.maxQuestions === undefined ? 2 : completion.maxQuestions, 'completionCheck.maxQuestions', 0, 20),
    },
    defaultSnoozeMinutes: asInteger(value.defaultSnoozeMinutes === undefined ? 60 : value.defaultSnoozeMinutes, 'defaultSnoozeMinutes', 1, 525600),
    maxDeliveryAttempts: asInteger(value.maxDeliveryAttempts === undefined ? 3 : value.maxDeliveryAttempts, 'maxDeliveryAttempts', 1, 10),
    quietHoursMode: 'inherit',
  };
}

function validateOperationShape(value) {
  const create = ['create_task', 'create_reminder', 'add_subtask'];
  assert(value.operation !== 'update_series', 'series_update_not_supported_mvp',
    'Series rule update is fail-closed until its recoverable current/future saga is enabled');
  if (create.includes(value.operation) && !value.clarificationNeeded) {
    assert(value.title, 'malformed_model_contract', 'Creation requires title unless clarification is needed');
  }
  if (value.operation === 'create_reminder') assert(value.taskKind === 'reminder' || value.taskKind === null, 'malformed_model_contract', 'create_reminder cannot create another task kind');
  if (value.taskKind === 'goal') {
    assert(value.operation === 'create_task', 'malformed_model_contract', 'A goal is created as a task');
    assert(!value.recurrence && !value.reminderPolicy, 'malformed_model_contract', 'A goal cannot have recurrence or reminder policy');
    assert(!value.schedule || value.schedule.kind === 'none', 'malformed_model_contract', 'A goal cannot have a deadline');
    assert(value.completionRequired !== true, 'malformed_model_contract', 'A goal does not use completion questions');
  }
  if (value.operation === 'create_reminder' && !value.clarificationNeeded) {
    assert(value.schedule && ['exact', 'date'].includes(value.schedule.kind), 'malformed_model_contract', 'create_reminder requires an actionable exact/date schedule or clarification');
  }
  if (value.recurrence) assert(['create_task', 'update_series'].includes(value.operation), 'malformed_model_contract', 'Recurrence is not allowed for this operation');
  if (value.operation === 'list_tasks') assert(value.listKind, 'malformed_model_contract', 'list_tasks requires listKind');
  if (value.operation === 'answer_task_question') assert(value.answerAction, 'malformed_model_contract', 'answer_task_question requires answerAction');
  if (['update_task', 'reschedule_task', 'complete_task', 'snooze_task', 'skip_occurrence', 'cancel_task', 'pause_series', 'resume_series', 'update_series', 'cancel_series', 'add_reminder'].includes(value.operation)) {
    assert(value.targetRef || value.clarificationNeeded, 'malformed_model_contract', 'Mutation requires a local targetRef or clarification');
  }
}

function validateSemanticAgainstTrusted(command, trusted, originalText) {
  assert(command && trusted, 'identity_permanent', 'Trusted semantic validation requires command and trusted context');
  const timezoneValues = [];
  if (command.schedule && command.schedule.timezone) timezoneValues.push(command.schedule.timezone);
  if (command.recurrence && command.recurrence.timezone) timezoneValues.push(command.recurrence.timezone);
  assert(timezoneValues.every((timezone) => timezone === trusted.timezone), 'timezone_mismatch', 'Model timezone must equal trusted runtime timezone');
  const source = new Date(trusted.sourceMessageDateIso);
  assert(Number.isFinite(source.getTime()), 'invalid_datetime', 'Trusted sourceMessageDateIso is invalid');
  const sourceLocalDate = localDateInTimezone(source, trusted.timezone);
  const candidateDates = [];
  if (command.schedule) {
    // Exact/date schedules are model-proposed calendar identity and must be
    // traceable to the user's text. Window bounds and recurrence dates are
    // validated structurally here and require their own explicit/default
    // planner policies; they are not silently granted by this date gate.
    if (['exact', 'date'].includes(command.schedule.kind) && command.schedule.localDate) {
      candidateDates.push(command.schedule.localDate);
    }
  }
  const text = String(originalText || '');
  for (const date of candidateDates) {
    const grounded = dateGroundedInText(date, text, sourceLocalDate, trusted.timezone, source);
    assert(grounded || command.clarificationNeeded === true, 'date_plausibility_requires_clarification', 'Model-proposed date is not grounded in original text');
  }
  if (command.schedule && command.schedule.kind === 'exact' && command.schedule.localTime) {
    const grounded = timeGroundedInText(command.schedule.localTime, text, trusted.timezone, source);
    assert(grounded || command.clarificationNeeded === true, 'time_plausibility_requires_clarification', 'Model-proposed time is not grounded in original text');
  }
  if (command.recurrence) {
    const recurrence = command.recurrence;
    const cadenceGrounded = recurrenceCadenceGroundedInText(recurrence.frequency, recurrence.interval, text);
    assert(cadenceGrounded || command.clarificationNeeded === true, 'recurrence_cadence_requires_clarification', 'Model-proposed recurrence frequency/interval is not grounded in original text');
    if (!recurrence.allDay) {
      const grounded = recurrenceTimeGroundedInText(recurrence.localTime, text, trusted.timezone, source);
      assert(grounded || command.clarificationNeeded === true, 'recurrence_time_requires_clarification', 'Model-proposed recurrence time is not grounded in original text or trusted time-of-day policy');
    }
    for (const date of [recurrence.startLocalDate, recurrence.endLocalDate].filter(Boolean)) {
      const grounded = dateGroundedInText(date, text, sourceLocalDate, trusted.timezone, source);
      assert(grounded || command.clarificationNeeded === true, 'recurrence_date_requires_clarification', 'Explicit recurrence start/end date is not grounded in original text');
    }
    if (recurrence.frequency === 'weekly') {
      const grounded = recurrenceWeekdaysGroundedInText(recurrence.byWeekday, text);
      assert(grounded || command.clarificationNeeded === true, 'recurrence_weekday_requires_clarification', 'Model-proposed recurrence weekdays are not grounded in original text');
    }
  }
  if (command.reminderPolicy && command.completionRequired === true) {
    const completion = command.reminderPolicy.completionCheck;
    assert(completion.enabled === true && completion.maxQuestions >= 1,
      'completion_policy_requires_question', 'Completion-required task must ask at least one completion question');
    assert(completion.maxQuestions === 1 || completion.repeatAfterMinutes < completion.answerTtlMinutes,
      'invalid_completion_question_cadence', 'Repeated completion question must occur before the current answer TTL expires');
  }
  return command;
}

function localDateInTimezone(date, timezone) {
  const parts = new Intl.DateTimeFormat('en-CA', { timeZone: timezone, year: 'numeric', month: '2-digit', day: '2-digit' }).formatToParts(date);
  const value = {};
  for (const part of parts) if (part.type !== 'literal') value[part.type] = part.value;
  return `${value.year}-${value.month}-${value.day}`;
}

function dateGroundedInText(date, text, sourceLocalDate, timezone, sourceInstant) {
  const normalized = String(text || '').normalize('NFKC').toLocaleLowerCase('ru-RU');
  if (!normalized.trim()) return false;
  const [year, month, day] = date.split('-').map(Number);
  if (normalized.includes(date)) return true;

  const numericDates = normalized.match(/(?:^|\D)(\d{1,2})[.\/-](\d{1,2})(?:[.\/-](\d{2,4}))?(?=\D|$)/gu) || [];
  for (const token of numericDates) {
    const match = token.match(/(\d{1,2})[.\/-](\d{1,2})(?:[.\/-](\d{2,4}))?/u);
    if (!match) continue;
    let parsedYear = match[3] ? Number(match[3]) : Number(sourceLocalDate.slice(0, 4));
    if (parsedYear < 100) parsedYear += 2000;
    if (Number(match[1]) === day && Number(match[2]) === month && parsedYear === year) return true;
  }

  const monthNames = [
    ['январ', 1], ['феврал', 2], ['март', 3], ['апрел', 4], ['ма(?:й|я)', 5], ['июн', 6],
    ['июл', 7], ['август', 8], ['сентябр', 9], ['октябр', 10], ['ноябр', 11], ['декабр', 12],
  ];
  for (const [stem, number] of monthNames) {
    const match = normalized.match(new RegExp(`(?:^|\\D)${day}\\s+${stem}[а-яё]*(?:\\s+(${year}))?(?=\\D|$)`, 'iu'));
    if (match && number === month && (year === Number(sourceLocalDate.slice(0, 4)) || match[1])) return true;
  }

  const targetDelta = Math.round((Date.parse(`${date}T00:00:00Z`) - Date.parse(`${sourceLocalDate}T00:00:00Z`)) / 86400000);
  if (hasNaturalToken(normalized, 'сегодня|today') && targetDelta === 0) return true;
  if (hasNaturalToken(normalized, 'вчера|yesterday') && targetDelta === -1) return true;
  if (hasNaturalToken(normalized, 'послезавтра|day\\s+after\\s+tomorrow') && targetDelta === 2) return true;
  if (hasNaturalToken(normalized, 'завтра|tomorrow') && !hasNaturalToken(normalized, 'послезавтра') && targetDelta === 1) return true;

  const relativeDays = normalized.match(/(?:через|in)\s+(\d{1,5})\s+(д(?:ень|ня|ней)|days?|недел(?:ю|и|ь)|weeks?)/iu);
  if (relativeDays) {
    const amount = Number(relativeDays[1]);
    const expected = /недел|week/iu.test(relativeDays[2]) ? amount * 7 : amount;
    if (targetDelta === expected) return true;
  }
  const relativeTime = normalized.match(/(?:через|in)\s+(\d{1,6})\s+(минут\w*|minutes?|час\w*|hours?)/iu);
  if (relativeTime && sourceInstant instanceof Date) {
    const multiplier = /час|hour/iu.test(relativeTime[2]) ? 3600000 : 60000;
    const expectedDate = localDateInTimezone(new Date(sourceInstant.getTime() + Number(relativeTime[1]) * multiplier), timezone);
    if (date === expectedDate) return true;
  }

  const weekdayNames = [
    [/понедельник|понедельника|monday/iu, 1], [/вторник|вторника|tuesday/iu, 2],
    [/сред(?:а|у|ы)|wednesday/iu, 3], [/четверг|четверга|thursday/iu, 4],
    [/пятниц(?:а|у|ы)|friday/iu, 5], [/суббот(?:а|у|ы)|saturday/iu, 6],
    [/воскресень(?:е|я)|sunday/iu, 0],
  ];
  const targetWeekday = new Date(`${date}T12:00:00Z`).getUTCDay();
