      const plannedRows = [];
      const previousById = {};
      if (resolution.targetReadBackExpectation) { plannedRows.push(resolution.targetRow); previousById[target.recordId] = target; }
      if (resolution.draftReadBackExpectation) { plannedRows.push(resolution.draftRow); previousById[row.recordId] = row; }
      return emitPlan(plannedRows, previousById, 'apply_mutation_draft', 'Изменение применено к выбранной задаче.').map((item) => {
        item.json._mutationDraftResolutionPlanned = true;
        return item;
      });
    }

} catch (error) {
  if (String(error.code || '') === 'concurrency_conflict' || String(error.code || '') === 'lease_conflict') {
    return outcome({ taskHandled: true, operation: 'task_deferred_retry', text: 'Задача сейчас обрабатывается планировщиком. Повторите команду чуть позже.', errorCode: String(error.code).slice(0, 80) });
  }
  return outcome({ taskHandled: true, operation: 'failed_review', text: 'Команда задач остановлена безопасно; изменения не применены.', errorCode: String(error.code || 'contract_violation').slice(0, 80) });
}
